"},{"path":"application/mapping/changes/diffSessionWorkflowService.ts","text":"import type { DiffSessionRun } from '../../../domain/mapping/changes/diffSessionWorkflow';
import { createHash } from 'node:crypto';
import { z } from 'zod';
import { requireAiEnabled } from '../../core/errors';
