52:       const receipt = accepted[session.id];
53:       if (session.version !== receipt.sessionVersion) throw new Error('Acceptance does not match saved proposal version');
54:       session.status = 'accepted'; session.acceptance = receipt;
55:       session.version = receipt.sessionVersion + 1; session.updatedAt = receipt.acceptedAt;
56:     }
57:     return sessions.filter(s => s.status !== 'archived').sort((a,b) => b.updatedAt.localeCompare(a.updatedAt));
58:   }
59:   async get(id: string) {
60:     const session = await this.repository.read(await this.projectId(), id);
61:     if (session.status === 'ready') {
62:       const accepted = (await this.source.projectCatalogs.loadChangeSessionAcceptances(session.projectId))[id];
63:       if (accepted) await this.finishAcceptance(session, accepted);
64:     }
65:     return session;
66:   }
67:   private async effectiveSummary(summary: import('../../../domain/mapping/changes/diagramChangeSession').ChangeSessionSummary) {
68:     if (summary.status === 'ready') {
69:       const receipt = (await this.source.projectCatalogs.loadChangeSessionAcceptances(summary.projectId))[summary.id];
70:       if (receipt) {
71:         if (summary.version !== receipt.sessionVersion) throw Error('Acceptance does not match saved proposal version');
72:         return { ...summary, status: 'accepted' as const, acceptance: receipt, version: receipt.sessionVersion + 1, updatedAt: receipt.acceptedAt };
73:       }
74:     }
75:     return summary;
76:   }
77:   async preview(id: string, documentId: string, version?: number) {
78:     const projectId = await this.projectId();
79:     const summary = await this.effectiveSummary(await this.repository.readSummary(projectId, id));
80:     if (!summary.documents.some(doc => doc.id === documentId)) throw Error('Unknown change-session document');
81:     if (summary.version === version) return null;
82:     const preview = await this.repository.readPreview(projectId, id, documentId);
83:     // Resolve acceptance against the exact generation returned by the scoped read.
84:     return { ...preview, ...await this.effectiveSummary(preview), document: preview.document };
85:   }
86:   /** Read one coherent generation without loading histories, receipts, or live Git files. */
87:   async readTreemaps(id: string, version?: number) {
88:     const projectId = await this.projectId();
89:     const summary = await this.effectiveSummary(await this.repository.readSummary(projectId, id));
90:     if (summary.version === version) return null;
91:     const stored = this.repository.readDiffTree ? await this.repository.readDiffTree(projectId, id)
92:       : await this.get(id).then(session => ({ summary: summarizeChangeSession(session), diffTree: session.diffTree }));
93:     const captured = await this.effectiveSummary(stored.summary);
94:     const documents: import('../../../domain/mapping/changes/diagramChangeSession').ChangePreviewDocument[] = [];
95:     for (let offset = 0; offset < captured.documents.length; offset += 4) {
96:       const previews = await Promise.all(captured.documents.slice(offset, offset + 4).map(doc => this.repository.readPreview(projectId, id, doc.id)));
97:       for (const preview of previews) {
98:         if ((await this.effectiveSummary(preview)).version !== captured.version) throw Error('VERSION_CONFLICT: changes updated while loading treemaps; retry');
99:         documents.push(preview.document);
100:       }
101:     }
102:     if ((await this.effectiveSummary(await this.repository.readSummary(projectId, id))).version !== captured.version)
103:       throw Error('VERSION_CONFLICT: changes updated while loading treemaps; retry');
104:     return { id, title: captured.title, version: captured.version, status: captured.status, head: captured.head,
105:       commits: captured.commits ?? [], hunks: stored.diffTree?.hunks ?? [], ...buildChangeTreemaps(stored.diffTree, documents) };
106:   }
107:   async discoverHunks(input: { repositoryId?: string; commits?: string[]; head?: string; comparisonBase?: string | null; offset: number; limit: number; includePatches: boolean }) {
108:     await this.projectId();
109:     if (!this.source.repositories) throw Error('Repository registry unavailable');
110:     const context = await this.source.repositories.resolveContext(input);
111:     const hunks = await this.captureHunks(context);
112:     return { ...context, ...this.hunkPage(hunks, input) };
113:   }
114:   private async captureHunks(context: RepositoryContext): Promise<GitDiffHunk[]> {
115:     if (!context.commits.length && context.comparisonBase === undefined) return [];
116:     if (!this.source.repositories?.captureHunks) throw Error('Git hunk capture unavailable');
117:     return this.source.repositories.captureHunks(context);
118:   }
119:   private hunkPage(hunks: GitDiffHunk[], input: { offset: number; limit: number; includePatches: boolean }) {
120:     return { total: hunks.length, offset: input.offset, nextOffset: input.offset + input.limit < hunks.length ? input.offset + input.limit : null,
121:       hunks: hunks.slice(input.offset, input.offset + input.limit).map(hunk => {
122:         if (input.includePatches) return hunk;
123:         const { patch: _, ...metadata } = hunk; return metadata;
124:       }) };
125:   }
126:   async readDiffTree(input: { changeSessionId: string; nodeIds?: string[]; hunkIds?: string[]; offset: number; limit: number; includePatches: boolean }) {
127:     const stored = this.repository.readDiffTree
128:       ? await this.repository.readDiffTree(await this.projectId(), input.changeSessionId)
129:       : await this.get(input.changeSessionId).then(session => ({ summary: summarizeChangeSession(session), diffTree: session.diffTree }));
130:     const summary = await this.effectiveSummary(stored.summary), tree = stored.diffTree;
131:     const context = { changeSessionId: summary.id, title: summary.title, version: summary.version, status: summary.status,
132:       repositoryId: summary.repositoryId, commits: summary.commits, head: summary.head, comparisonBase: summary.comparisonBase, documents: summary.documents, changes: summary.changes };
133:     if (!tree) return { ...context, diffTree: null, ...this.hunkPage([], input), unmappedNodeIds: [] };
134:     const selection = input.nodeIds ? resolveDiffTreeHunks(tree, input.nodeIds) : undefined;
135:     const ids = input.hunkIds ?? selection?.hunkIds;
136:     if (ids?.some(id => !tree.hunks.some(hunk => hunk.id === id))) throw Error('Unknown DiffTree hunk');
137:     const hunks = ids ? tree.hunks.filter(hunk => ids.includes(hunk.id)) : tree.hunks;
138:     return { ...context, diffTree: { ...diffTreeSummary(tree), diagram: tree.revision.diagram,
139:       nodes: diffTreeNodes(tree), mappings: tree.mappings }, ...this.hunkPage(hunks, input), unmappedNodeIds: selection?.unmappedNodeIds ?? [] };
140:   }
141:   private async finishAcceptance(session: DiagramChangeSession, acceptance: ChangeSessionAcceptance) {
142:     if (session.version !== acceptance.sessionVersion) throw new Error('Acceptance does not match saved proposal version');
143:     session.status = 'accepted'; session.acceptance = acceptance;
144:     session.version = acceptance.sessionVersion + 1; session.updatedAt = acceptance.acceptedAt;
145:     await this.repository.write(session, { documents: [], receipts: [] });
146:   }
147:   async accept(input: { changeSessionId: string; requestId: string; expectedVersion: number }) {
148:     return this.serialize(input.changeSessionId, async () => {
149:       const session = await this.get(input.changeSessionId);
150:       if (session.acceptance) {
151:         if (session.acceptance.requestId !== input.requestId || session.acceptance.sessionVersion !== input.expectedVersion)
152:           throw new Error('REQUEST_ID_CONFLICT: proposal already accepted');
153:         return summarizeChangeSession(session);
154:       }
155:       if (session.version !== input.expectedVersion) throw new Error('VERSION_CONFLICT: reread change session');
156:       if (session.status !== 'ready') throw new Error('Only a ready change session can be accepted');
157:       this.validateReady(session);
158:       const affected = session.documents.filter(d => session.changes.some(c => c.documentId === d.id));
159:       // Captured drafts must not silently replace newer edits in any live workspace.
160:       for (const canvas of this.bridge.list().filter(c => c.projectId === session.projectId)) for (const live of canvas.documents) {
161:         const doc = affected.find(d => d.id === live.documentId || !!d.representationId && d.representationId === live.representationId);
162:         if (!doc?.baseline) continue;
163:         const current = await this.bridge.dispatch(canvas.canvasId, { method: 'document-state', documentId: live.documentId }) as LiveDocumentState;
164:         if (stateKey(current.document) !== stateKey(doc.baseline.document) || current.name !== doc.name)
165:           throw new Error('VERSION_CONFLICT: live canvas changed since capture; create a new proposal');
166:       }
167:       const acceptance = await this.source.projectCatalogs.acceptCanvasChanges(session.projectId, {
168:         changeSessionId: session.id, sessionVersion: session.version, requestId: input.requestId, changeIds: session.changes.map(c => c.id),
169:         documents: affected.map(doc => ({ documentId: doc.id, representationId: doc.representationId, expectedRevisionId: doc.savedRevisionId,
170:           name: doc.name, repositoryId: doc.repositoryId ?? session.repositoryId, document: doc.proposed.document, history: this.controller(doc).exportHistory() }))
171:       });
172:       // The catalog receipt recovers this step after a crash or a failed session write.
173:       await this.finishAcceptance(session, acceptance);
174:       return summarizeChangeSession(session);
175:     });
176:   }
177:   async create(input: { title: string; description?: string; canvasId?: string; requestId: string; repositoryId?: string; commits?: string[]; head?: string; comparisonBase?: string | null; diffTree?: DiffTreeInput }, captured?: ChangeSessionCapture) {
178:     const projectId = await this.projectId();
179:     const id = `change-${createHash('sha256').update(`${projectId}:${input.requestId}`).digest('hex').slice(0,32)}`;
180:     return this.serialize(id, async () => {
181:       const signature = JSON.stringify(captured ? { input, captureHash: stateKey(captured) } : input);
182:       const prior = await this.repository.read(projectId, id).catch(error => { if (error.code === 'ENOENT') return undefined; throw error; });
183:       if (prior) {
184:         if (prior.receipts.create?.signature !== signature) throw new Error('REQUEST_ID_CONFLICT');
185:         return prior.receipts.create.result;
186:       }
187:       const capture = captured ?? await this.capture(input);
188:       if (capture.projectId !== projectId) throw Error('Captured context belongs to another project');
189:       const { context, hunks } = capture;
190:       if (input.diffTree && !context) throw Error('DiffTree requires pinned repository context');
191:       const diffTree = context ? input.diffTree ? writeDiffTree(input.diffTree, hunks) : defaultDiffTree(hunks) : undefined;
192:       const documents = new Map(capture.documents.map(doc => [doc.id, structuredClone(doc)]));
193:       const result = { ...context, ...(diffTree ? { diffTree: diffTreeSummary(diffTree) } : {}), changeSessionId: id, canvasId: id, version: 0, documents: [...documents.values()].map(d => ({ documentId: d.id, name: d.name })) };
194:       const now = new Date().toISOString();
195:       await this.repository.write({ ...context, ...(diffTree ? { diffTree } : {}), schemaVersion: 1, id, projectId, title: input.title, description: input.description ?? '', status: 'draft', version: 0,
196:         createdAt: now, updatedAt: now, documents: [...documents.values()], changes: [], receipts: { create: { signature, result } } });
197:       return result;
198:     });
199:   }
200:   /** Freeze exactly the inputs the workflow analyzes, without creating a proposal. */
201:   async capture(input: { repositoryId?: string; commits?: string[]; head?: string; comparisonBase?: string | null; canvasId?: string; baselineChangeSessionId?: string }): Promise<ChangeSessionCapture> {
202:     const projectId = await this.projectId();
203:     if (input.baselineChangeSessionId) {
204:       const original = await this.get(input.baselineChangeSessionId);
205:       if (!original.repositoryId || !original.commits || !original.head || !original.diffTree) throw Error('Baseline session has no pinned Git context');
206:       if (input.repositoryId || input.commits || input.head || input.canvasId || input.comparisonBase !== undefined) throw Error('A baseline session supplies its own repository, commits and canvases');
207:       const documents = original.documents.filter(doc => doc.baseline).map(doc => {
208:         const baseline = structuredClone(doc.baseline!);
209:         return { id: doc.id, name: doc.name, representationId: doc.representationId, savedRevisionId: doc.savedRevisionId,
210:           repositoryId: doc.repositoryId ?? original.repositoryId, baseline, proposed: structuredClone(baseline),
211:           history: this.forkHistory(baseline), version: 0, past: [], future: [] } satisfies ChangeSessionDocument;
212:       });
213:       if (!documents.length) throw Error('Baseline session has no original canvases');
214:       return { projectId, baselineChangeSessionId: original.id,
215:         context: { repositoryId: original.repositoryId, commits: [...original.commits], head: original.head, ...(original.comparisonBase !== undefined ? { comparisonBase: original.comparisonBase } : {}) },
216:         hunks: structuredClone(original.diffTree.hunks), documents };
217:     }
218:     if (!this.source.repositories && (input.repositoryId || input.commits?.length || input.head)) throw Error('Repository registry unavailable');
219:     const context = await this.source.repositories?.resolveContext(input);
220:     const hunks = context ? await this.captureHunks(context) : [];
221:     const documents = new Map<string, ChangeSessionDocument>();
222:     const catalog = await (this.source.projectCatalogs.loadCurrentRepresentationCatalog?.(projectId) ?? this.source.projectCatalogs.loadRepresentationCatalog(projectId));
223:     for (const rep of Object.values(catalog.representations).filter(r => r.status === 'settled' && (!context || r.repositoryId === context.repositoryId))) {
224:       const revision = catalog.revisions[rep.currentRevisionId];
225:       const baseline = { document: documentFromRevision(revision), canvas: initialCanvasState() };
226:       documents.set(rep.id, { id: rep.id, name: rep.name, repositoryId: rep.repositoryId, representationId: rep.id, savedRevisionId: revision.id, history: this.forkHistory(baseline),
227:         baseline, proposed: structuredClone(baseline), version: 0, past: [], future: [] });
228:     }
229:     const live = this.bridge.list().filter(c => c.projectId === projectId && (!input.canvasId || c.canvasId === input.canvasId));
230:     if (input.canvasId && !live.length) throw new Error('Unknown project canvas');
231:     if (!input.canvasId && live.length > 1) throw new Error('Multiple live workspaces: specify canvasId to capture drafts');
232:     for (const canvas of live) for (const doc of canvas.documents) {
233:       const saved = catalog.representations[doc.representationId ?? doc.documentId];
234:       if (context && (saved?.repositoryId ?? doc.repositoryId) !== context.repositoryId) continue;
235:       const snapshot = await this.bridge.dispatch(canvas.canvasId, { method: 'snapshot', documentId: doc.documentId, payload: { currentRevisions: true } }) as LiveDocumentSnapshot;
236:       if (context && (saved?.repositoryId ?? snapshot.repositoryId ?? doc.repositoryId) !== context.repositoryId) throw Error('Canvas repository changed during capture');
237:       for (const revision of snapshot.revisions ?? []) importDiagramRevision(revision);
238:       const baseline = structuredClone({ document: snapshot.document, canvas: snapshot.canvas });
239:       const key = snapshot.representationId ?? doc.representationId ?? doc.documentId;
240:       documents.set(key, { id: key, name: snapshot.name, repositoryId: saved?.repositoryId ?? snapshot.repositoryId ?? doc.repositoryId, representationId: snapshot.representationId ?? doc.representationId,
241:         history: this.forkHistory(baseline),
242:         savedRevisionId: snapshot.revisionId, capturedVersion: snapshot.version, baseline, proposed: structuredClone(baseline), version: 0, past: [], future: [] });
243:     }
244:     return { projectId, context, hunks, documents: [...documents.values()] };
245:   }
246:   private forkHistory(state: ChangeDocumentState, history?: import('../../../domain/core/diagrams/canvasHistory').CanvasHistoryRecord) {
247:     const context = this.historyService.openContext(state.document, state.canvas, history);
248:     return this.historyService.forkContext(context, state.canvas);
249:   }
250:   /** Replay a completed bound MCP mutation before consulting its now-stale version. */
251:   async request<T>(id: string, requestId: string, signature: string, execute: () => Promise<T>): Promise<T> {
252:     return this.serialize(`api:${id}`, async () => {
253:       const key = `api:${requestId}`, existing = (await this.get(id)).receipts[key];
254:       if (existing) { if (existing.signature !== signature) throw new Error('REQUEST_ID_CONFLICT'); return existing.result as T; }
255:       const result = await execute();
256:       await this.serialize(id, async () => {
257:         const session = await this.get(id);
258:         session.receipts[key] = { signature, result };
259:         await this.repository.write(session, { documents: [], receipts: [key] });
260:       });
261:       return result;
262:     });
263:   }
264:   async descriptor(id: string) { const s = await this.get(id); return [{ canvasId: s.id, projectId: s.projectId,
265:     documents: s.documents.map(d => ({ documentId: d.id, name: d.name, repositoryId: d.repositoryId, representationId: d.representationId })) }]; }
266:   private document(session: DiagramChangeSession, id: string) { const doc = session.documents.find(d => d.id === id); if (!doc) throw new Error('Unknown change-session document'); return doc; }
267:   async snapshot(id: string, documentId: string): Promise<LiveDocumentSnapshot> {
268:     const s = await this.get(id), doc = this.document(s, documentId);
269:     return { ...structuredClone(doc.proposed), name: doc.name, repositoryId: doc.repositoryId, representationId: doc.representationId, revisionId: doc.savedRevisionId,
270:       version: doc.version, contextId: doc.history?.contextId, canUndo: !!(doc.history?.past.length || doc.past.length), canRedo: !!(doc.history?.future.length || doc.future.length) } as LiveDocumentSnapshot;
271:   }
272:   private async mutate<T>(id: string, requestId: string, signature: string, fn: (s: DiagramChangeSession) => T) {
273:     return this.serialize(id, async () => {
274:       const s = await this.get(id), key = `request:${requestId}`, receipt = s.receipts[key];
275:       if (receipt) { if (receipt.signature !== signature) throw new Error('REQUEST_ID_CONFLICT'); return receipt.result as T; }
276:       if (s.status === 'archived') throw new Error('Change session is archived');
277:       if (s.status === 'accepted') throw new Error('Change session is accepted and cannot be edited');
278:       if (Object.keys(s.receipts).length >= 2000) throw new Error('Change session request capacity reached');
279:       const before = new Map(s.documents.map(doc => [doc.id, doc.version]));
280:       const previousDiffTree = s.diffTree;
281:       const result = fn(s);
282:       s.version++; s.updatedAt = new Date().toISOString(); s.receipts[key] = { signature, result };
283:       await this.repository.write(s, { documents: s.documents.filter(doc => before.get(doc.id) !== doc.version).map(doc => doc.id), receipts: [key], diffTree: s.diffTree !== previousDiffTree });
284:       return result;
285:     });
286:   }
287:   async apply(id: string, documentId: string, version: number, operations: DiagramOperation[], requestId: string) {
288:     return this.mutate(id, requestId, JSON.stringify({ documentId, version, operations }), s => {
289:       const doc = this.document(s, documentId);
290:       const controller = this.controller(doc);
291:       const result = controller.applyUpdate(version, operations);
292:       this.record(doc, controller);
293:       this.refreshChanges(s, new Set([documentId])); s.status = 'draft';
294:       return result;
295:     });
296:   }
297:   private controller(doc: ChangeSessionDocument) {
298:     // Older proposals are imported once, preserving their available undo states.
299:     if (!doc.history) {
300:       const baseline = doc.baseline ?? doc.past[0] ?? doc.proposed;
301:       const context = this.historyService.openContext(baseline.document, baseline.canvas);
302:       const record = this.historyService.exportContext(context);
303:       const states = [...doc.past, doc.proposed, ...[...doc.future].reverse()];
304:       const ids: string[] = [];
305:       for (const state of states) {
306:         this.historyService.append(context, state.document, state.canvas);
307:         ids.push(this.historyService.state(context).checkpointId);
308:       }
309:       const migrated = this.historyService.exportContext(context);
310:       states.forEach((state, index) => {
311:         if (state.nodeOrigins) migrated.snapshots[ids[index]].nodeOrigins = structuredClone(state.nodeOrigins);
312:       });
313:       migrated.baselineId = record.baselineId;
314:       migrated.headId = ids[doc.past.length];
315:       migrated.past = ids.slice(0, doc.past.length);
316:       migrated.future = ids.slice(doc.past.length + 1).reverse();
317:       doc.history = migrated;
318:     }
319:     return new MappingDocumentController(doc.proposed.document, doc.proposed.canvas, doc.version, undefined, undefined, doc.history, this.historyService);
320:   }
321:   private record(doc: ChangeSessionDocument, controller: MappingDocumentController) {
322:     const snapshot = controller.getSnapshot();
323:     doc.history = controller.exportHistory();
324:     doc.proposed = { document: snapshot.document, canvas: snapshot.canvas,
325:       nodeOrigins: doc.history.snapshots[doc.history.headId].nodeOrigins };
326:     doc.version = snapshot.version;
327:     // Canonical history owns undo/redo; these remain empty for old readers.
328:     doc.past = []; doc.future = [];
329:   }
330:   async createDocument(id: string, name: string, requestId: string) {
331:     return this.mutate(id, requestId, JSON.stringify({ name }), s => {
332:       const documentId = `draft-${randomUUID()}`;
333:       s.documents.push({ id: documentId, name, repositoryId: s.repositoryId, baseline: null, proposed: { document: mappingDocumentFromScene(singleDiagramScene('[New diagram]')),
334:         canvas: initialCanvasState() }, version: 0, past: [], future: [] });
335:       this.controller(s.documents[s.documents.length - 1]);
336:       this.refreshChanges(s, new Set([documentId])); s.status = 'draft'; return { documentId };
337:     });
338:   }
339:   private refreshChanges(s: DiagramChangeSession, affected: ReadonlySet<string>) {
340:     const changes: DiagramChange[] = [];
341:     for (const doc of s.documents) {
342:       if (!affected.has(doc.id)) { changes.push(...s.changes.filter(change => change.documentId === doc.id)); continue; }
343:       if (!doc.baseline) { changes.push({ id: `canvas:${doc.id}`, documentId: doc.id, title: doc.name, type: 3, reasons: [], dependsOn: [] }); continue; }
344:       if (stateKey([doc.baseline.document.revisionReviews ?? {}, doc.baseline.document.revisionSelections ?? {}]) !== stateKey([doc.proposed.document.revisionReviews ?? {}, doc.proposed.document.revisionSelections ?? {}]))
345:         changes.push({ id: `variants:${doc.id}`, documentId: doc.id, title: `${doc.name}: subtree variants`, type: 1, reasons: [], dependsOn: [] });
346:       const before = canvasDisplayNodes(doc.baseline.document, doc.baseline.canvas, 0);
347:       const after = canvasDisplayNodes(doc.proposed.document, doc.proposed.canvas, 0);
348:       const candidates = new Map([...before, ...after].filter(n => n.layout === 'grid' && n.kind === 'diagram').map(n => [n.id, n]));
349:       for (const [nodeId, node] of candidates) {
350:         const a = before.find(n => n.id === nodeId), b = after.find(n => n.id === nodeId);
351:         const contentChanged = JSON.stringify(a) !== JSON.stringify(b);
352:         const incident = (state: ChangeDocumentState) => state.document.edges.filter(e => e.source.displayNodeId === nodeId || e.target.displayNodeId === nodeId);
353:         if (!contentChanged && JSON.stringify(incident(doc.baseline)) === JSON.stringify(incident(doc.proposed))) continue;
354:         changes.push({ id: `diagram:${doc.id}:${nodeId}`, documentId: doc.id, nodeId,
355:           title: node.layout === 'grid' ? node.content?.ascii.split('\n')[0].trim().slice(0,200) || nodeId : nodeId,
356:           type: a ? 1 : 2, reasons: [], dependsOn: [] });
357:       }
358:     }
359:     s.changes = changes.map(change => {
360:       const previous = s.changes.find(c => c.id === change.id);
361:       return previous ? { ...change, title: previous.title, reasons: previous.reasons, dependsOn: previous.dependsOn,
362:         type: change.type === 1 && previous.type === 4 ? 4 : change.type } : change;
363:     });
364:   }
365:   async update(input: { changeSessionId: string; requestId: string; expectedVersion: number; title?: string; status?: 'draft'|'ready'|'archived';
366:     changes?: DiagramChange[]; migrations?: DiagramMigration[]; diffTree?: DiffTreeInput; action?: 'undo'|'redo'|'reset'; documentId?: string }) {
367:     let captured: GitDiffHunk[] | undefined;
368:     if (input.diffTree) {
369:       const session = await this.get(input.changeSessionId);
370:       if (!session.repositoryId || !session.head || !session.commits) throw Error('DiffTree requires pinned repository context');
371:       if (!session.diffTree) captured = await this.captureHunks({ repositoryId: session.repositoryId, head: session.head, commits: session.commits, comparisonBase: session.comparisonBase });
372:     }
373:     return this.mutate(input.changeSessionId, input.requestId, JSON.stringify(input), s => {
374:       if (s.version !== input.expectedVersion) throw new Error('VERSION_CONFLICT: reread change session');
375:       if (input.action) {
376:         if (!input.documentId) throw new Error('documentId is required');
377:         const doc = this.document(s, input.documentId);
378:         const controller = this.controller(doc);
379:         if (input.action === 'reset') {
380:           if (!doc.baseline) throw new Error('A new canvas has no baseline');
381:           controller.reset();
382:         } else {
383:           const snapshot = controller.getSnapshot();
384:           if (input.action === 'undo' ? !snapshot.canUndo : !snapshot.canRedo) throw new Error('No history available');
385:           controller.undo(input.action === 'redo');
386:         }
387:         this.record(doc, controller);
388:         this.refreshChanges(s, new Set([doc.id])); s.status = 'draft';
389:       }
390:       if (input.diffTree) {
391:         s.diffTree = writeDiffTree(input.diffTree, s.diffTree?.hunks ?? captured!, s.diffTree);
392:         s.status = 'draft';
